"""Daemon install's generated bytes remain those recorded from origin/main.

Fixtures were rendered by executing the unmodified renderer source at
ac9e841c, not by the parameterized code under test. Pins: binary
/recorded/bin/brnrd, PATH /recorded/bin:/usr/bin, repo /recorded/repo,
macOS user home /recorded/home, Linux cfg {} (default memory limits).
Only the temporary macOS user-home prefix is normalized for the comparison.
"""

from pathlib import Path

import pytest

from brr import cli, daemon_install
from brr.daemon_install import linux, macos


@pytest.mark.parametrize("system", ["Linux", "Darwin"])
def test_daemon_install_argv_writes_origin_main_bytes(system, tmp_path, monkeypatch):
    monkeypatch.setenv("PATH", "/recorded/bin:/usr/bin")
    monkeypatch.setattr(linux, "supported", lambda: system == "Linux")
    monkeypatch.setattr(daemon_install, "_is_macos", lambda: system == "Darwin")
    monkeypatch.setattr(Path, "home", lambda: tmp_path)
    monkeypatch.setattr(macos.shutil, "which", lambda _name: "/recorded/bin/brnrd")
    monkeypatch.setattr(macos, "resolve_workdir", lambda: Path("/recorded/repo"))
    monkeypatch.setattr(linux, "resolve_brr_bin", lambda: "/recorded/bin/brnrd")
    monkeypatch.setattr(linux, "resolve_workdir", lambda: Path("/recorded/repo"))
    monkeypatch.setenv("XDG_CONFIG_HOME", str(tmp_path / "config"))
    monkeypatch.setenv("XDG_STATE_HOME", str(tmp_path / "state"))
    monkeypatch.setattr(linux, "linger_enabled", lambda _user: True)
    calls = []

    def fake(command, *, check=True):
        import subprocess
        calls.append(command)
        return subprocess.CompletedProcess(command, 0)

    monkeypatch.setattr(linux, "_run", fake)
    cli.main(["daemon", "install", "--no-start"])
    fixtures = Path(__file__).parent / "fixtures" / "daemon_install"
    if system == "Linux":
        actual = linux.unit_path().read_bytes()
        recorded = (fixtures / "ac9e841c.service").read_bytes()
        assert calls == [
            ["systemctl", "--user", "daemon-reload"],
            ["systemctl", "--user", "enable", "brr.service"],
        ]
    else:
        actual = macos.plist_path().read_bytes().replace(
            str(tmp_path).encode(), b"/recorded/home",
        )
        recorded = (fixtures / "ac9e841c.plist").read_bytes()
        assert calls == []
    assert actual == recorded
